    "title": "TL;DW: Anthropic's $2T IPO, Zuck's Manifesto, Nvidia's $500B Bet & Grok's Comeback",
    "creator": "All-In Podcast",
    "youtubeUrl": "https://www.youtube.com/watch?v=kVzYGVJ8zUk",
    "isVideo": true,
